// X_0(N)^* models for squarefree N with genus(X_0(N)^*) = 5.
// Auto-generated by scripts/gen_genus_models.m. Curves are in the canonical
// saturated-HNF star basis. Cusp forms not stored.
// All curves of this genus live in the single shared projective space P below.
//   models[N]`curve          : the curve X_0(N)^* in P
//   models[N]`special_points : number of special (CM + cusp) rational points

Q := Rationals();
P<x, y, z, w, t> := ProjectiveSpace(Q, 4);
ModelRec := recformat< N, genus, squarefree, hyperelliptic, special_points, 
curve >;
models := AssociativeArray();


