hyperelliptic := false, special_points := 9, curve := Curve(P, [
    x*z - y^2 + y*w + 4*y*t - z^2 - 3*z*t - 4*w*t - 2*t^2,
    x*w - y*z + 3*y*t - z*w + z*t - 3*w*t - 5*t^2,
    x*t - y*w + z*w - z*t + w^2 - 2*w*t - t^2
]) >;


